@layer base {
  * {
    @apply border-border outline-ring/50;
  }

  * {
    scrollbar-width: thin;
    scrollbar-color: var(--scrollbar-thumb) var(--scrollbar-track);
  }

  /* Always show scrollbar for webkit browsers (Chrome, Safari, Edge) */
  ::-webkit-scrollbar {
    width: calc(10px * var(--scale-compact));
    height: calc(10px * var(--scale-compact));
    -webkit-appearance: none;
  }

  ::-webkit-scrollbar-track {
    background: var(--scrollbar-track);
    border-radius: 5px;
  }

  ::-webkit-scrollbar-thumb {
    background: var(--scrollbar-thumb);
    border-radius: 5px;
    border: 2px solid transparent;
    background-clip: padding-box;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: oklch(var(--muted-foreground) / 0.7);
    background-clip: padding-box;
  }

  ::-webkit-scrollbar-thumb:active {
    background: oklch(var(--foreground) / 0.6);
    background-clip: padding-box;
  }

  html {
    @apply overflow-x-hidden;
    font-size: calc(14px);
  }
  body {
    @apply bg-background text-foreground has-[div[data-variant='inset']]:bg-sidebar min-h-svh w-full;
    font-size: calc(12px * var(--scale-compact));
    letter-spacing: var(--tracking-normal);
  }

  /* Override Radix scroll locking for sticky headers */
  body[data-scroll-locked] {
    overflow: unset !important;
    pointer-events: auto !important;
  }

  /* Override Radix Popper z-index to prevent covering sticky header */
  [data-radix-popper-content-wrapper] {
    z-index: 60 !important;
  }

  /* Cursor pointer for buttons */
  button:not(:disabled),
  [role="button"]:not(:disabled) {
    cursor: pointer;
  }

  /* Prevent focus zoom on mobile devices */
  @media screen and (max-width: 767px) {
    input,
    select,
    textarea {
      font-size: calc(12px * var(--scale-compact));
    }
  }

  /* Sidebar scrollbar styles - similar to global but using sidebar colors */
  [data-sidebar="content"] {
    scrollbar-width: thin;
    scrollbar-color: oklch(var(--sidebar-foreground) / 0.2) transparent;
  }

  [data-sidebar="content"]::-webkit-scrollbar {
    width: calc(10px * var(--scale-compact));
    height: calc(10px * var(--scale-compact));
    -webkit-appearance: none;
  }

  [data-sidebar="content"]::-webkit-scrollbar-track {
    background: transparent;
    border-radius: 5px;
  }

  [data-sidebar="content"]::-webkit-scrollbar-thumb {
    background: oklch(var(--sidebar-foreground) / 0.2);
    border-radius: 5px;
    border: 2px solid transparent;
    background-clip: padding-box;
  }

  [data-sidebar="content"]::-webkit-scrollbar-thumb:hover {
    background: oklch(var(--sidebar-foreground) / 0.3);
    background-clip: padding-box;
  }

  [data-sidebar="content"]::-webkit-scrollbar-thumb:active {
    background: oklch(var(--sidebar-foreground) / 0.4);
    background-clip: padding-box;
  }
  .maplibregl-popup-content {
    @apply bg-transparent! shadow-none! p-0! rounded-none!;
  }
  .maplibregl-popup-tip {
    @apply hidden!;
  }
}

@utility container {
  margin-inline: auto;
  padding-inline: calc(2rem * var(--scale-compact));
}

@utility no-scrollbar {
  /* Hide scrollbar for Chrome, Safari and Opera */
  &::-webkit-scrollbar {
    display: none;
  }
  /* Hide scrollbar for IE, Edge and Firefox */
  -ms-overflow-style: none; /* IE and Edge */
  scrollbar-width: none; /* Firefox */
}

@utility faded-bottom {
  @apply after:pointer-events-none after:absolute after:start-0 after:bottom-0 after:hidden after:h-32 after:w-full after:rounded-b-2xl after:bg-[linear-gradient(180deg,transparent_10%,var(--background)_70%)] md:after:block;
}

/* styles.css */
.CollapsibleContent {
  overflow: hidden;
}
.CollapsibleContent[data-state="open"] {
  animation: slideDown 300ms ease-out;
}
.CollapsibleContent[data-state="closed"] {
  animation: slideUp 300ms ease-out;
}

@keyframes slideDown {
  from {
    height: 0;
  }
  to {
    height: var(--radix-collapsible-content-height);
  }
}

@keyframes slideUp {
  from {
    height: var(--radix-collapsible-content-height);
  }
  to {
    height: 0;
  }
}

/* ML Gradient Border Animation */
@keyframes gradient-shift {
  0%, 100% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
}

.animate-gradient-shift {
  background-size: 200% 200%;
  animation: gradient-shift 3s ease-in-out infinite;
}

/* Respect reduced motion preferences */
@media (prefers-reduced-motion: reduce) {
  .animate-gradient-shift {
    animation: none;
    background-size: 100% 100%;
  }
}

/* POS Marker Pulse Animation - Optimized for smoothness */
@keyframes marker-pulse {
  0% {
    transform: scale(1) translateZ(0);
    opacity: 0.8;
  }
  50% {
    transform: scale(1.6) translateZ(0);
    opacity: 0.4;
  }
  100% {
    transform: scale(1) translateZ(0);
    opacity: 0;
  }
}

.animate-marker-pulse {
  animation: marker-pulse 2.5s cubic-bezier(0.4, 0, 0.2, 1) infinite;
  /* GPU acceleration for smooth animation */
  will-change: transform, opacity;
  transform-origin: center;
  backface-visibility: hidden;
}

/* Respect reduced motion for marker pulse */
@media (prefers-reduced-motion: reduce) {
  .animate-marker-pulse {
    animation: none;
  }
}
